function validate([n, queries]) {
  if (!Number.isInteger(n) || n < 1 || n > 10000) return 'n is between 1 and 10^4.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 50000) return 'queries needs 1 to 5 * 10^4 entries.';
  for (const q of queries) {
    if (!Array.isArray(q) || q.length !== 3) return 'Each query is [type, index, val].';
    const [type, index, val] = q;
    if (type !== 0 && type !== 1) return 'type is 0 (row) or 1 (column).';
    if (!Number.isInteger(index) || index < 0 || index >= n) return 'index is between 0 and n - 1.';
    if (!Number.isInteger(val) || val < 0 || val > 100000) return 'val is between 0 and 10^5.';
  }
  return null;
}

