function matrixSumQueries(n, queries) {
  const grid = Array.from({ length: n }, () => new Array(n).fill(0));
  for (const [type, index, val] of queries) {
    for (let k = 0; k < n; k++) {
      if (type === 0) grid[index][k] = val;
      else grid[k][index] = val;
    }
  }
  let sum = 0;
  for (const row of grid) for (const cell of row) sum += cell;
  return sum;
}

