function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    // Either a huge grid with mostly distinct lines, or a smaller one where lines are overwritten many times.
    const n = rand() < 0.5 ? pick(5000, 10000) : pick(20, 400);
    const queries = Array.from({ length: 2000 }, () => [pick(0, 1), pick(0, n - 1), pick(0, 100000)]);
    return [n, queries];
  }
  const n = pick(1, 5);
  const count = pick(1, 10);
  const top = rand() < 0.3 ? 100000 : 9;
  const queries = Array.from({ length: count }, () => [pick(0, 1), pick(0, n - 1), pick(0, top)]);
  return [n, queries];
}
